<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuth } from '../stores/auth'
import { tradingApi } from '../api/trading'
import { profileApi } from '../api/profile'
import OrdersView from './OrdersView.vue'

const auth=useAuth(),router=useRouter(),active=ref('dashboard'),account=ref<any>(null),orders=ref<any[]>([]),error=ref(''),loading=ref(true),profile=ref<any>({}),asset=ref<any>(null),holdings=ref<any[]>([]),history=ref<any[]>([]),profileMessage=ref(''),profileError=ref(''),savingProfile=ref(false)
const items=[{key:'dashboard',label:'我的看板',icon:'▦'},{key:'profile',label:'个人信息',icon:'◉'},{key:'orders',label:'我的订单',icon:'▤'},{key:'assets',label:'资产与持仓',icon:'◇'},{key:'enterprise',label:'企业认证',icon:'▣'},{key:'risk',label:'风险测评',icon:'△'},{key:'advisor',label:'投顾服务',icon:'♙'}]
const currentTitle=computed(()=>items.find(item=>item.key===active.value)?.label||'我的看板')
const money=(value:any)=>Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const totalHoldingValue=computed(()=>holdings.value.reduce((sum,h)=>sum+Number(h.market_value||0),0))
const totalProfit=computed(()=>holdings.value.reduce((sum,h)=>sum+Number(h.profit_loss||0),0))
const chartPoints=computed(()=>{const rows=history.value;if(!rows.length)return '';const w=560,h=180,p=14;const values=rows.map(x=>Number(x.total_asset||0));const min=Math.min(...values),max=Math.max(...values),span=max-min||1;return rows.map((x,i)=>`${p+i*((w-p*2)/Math.max(1,rows.length-1))},${h-p-((Number(x.total_asset)-min)/span)*(h-p*2)}`).join(' ')})
const chartMin=computed(()=>history.value.length?Math.min(...history.value.map(x=>Number(x.total_asset||0))):0)
const chartMax=computed(()=>history.value.length?Math.max(...history.value.map(x=>Number(x.total_asset||0))):0)
const cashShare=computed(()=>{const total=Number(asset.value?.total_asset||0);return total?Math.round(Number(asset.value?.cash_balance||0)/total*100):0})
const allocationStyle=computed(()=>`conic-gradient(#3a6cf4 0 ${cashShare.value}%, #42b8ca ${cashShare.value}% 100%)`)
const maxProfit=computed(()=>Math.max(1,...holdings.value.map(h=>Math.abs(Number(h.profit_loss||0)))))
async function refresh(){const [accountRes,orderRes,summaryRes,historyRes]=await Promise.all([tradingApi.account(),tradingApi.orders(),profileApi.summary(),profileApi.assetHistory(60)]);account.value=accountRes.data.data;orders.value=orderRes.data.data;const summary=summaryRes.data.data;profile.value=summary.profile||{};asset.value=summary.latest_asset||null;holdings.value=summary.holdings||[];history.value=historyRes.data.data.items||[]}
async function saveProfile(){savingProfile.value=true;profileMessage.value='';profileError.value='';try{profile.value=(await profileApi.updateProfile({age:profile.value.age,occupation:profile.value.occupation||'',region:profile.value.region||'',investment_goal:profile.value.investment_goal||'',investment_horizon_years:profile.value.investment_horizon_years||5,liquidity_preference:profile.value.liquidity_preference||'medium'})).data.data;profileMessage.value='个人信息已更新'}catch(e:any){profileError.value=e.response?.data?.detail||e.message}finally{savingProfile.value=false}}
async function logout(){await auth.logout();await router.push('/login')}
onMounted(async()=>{try{await refresh()}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{loading.value=false}})
</script>
<template>
<div class="portal-shell customer-portal"><aside class="portal-sidebar"><div class="portal-brand"><div class="portal-logo">W</div><div><strong>财富管理平台</strong><small>客户服务端</small></div></div><div class="portal-user"><div class="portal-avatar">{{(auth.me.value?.display_name||'客').slice(0,1)}}</div><div><strong>{{auth.me.value?.display_name}}</strong><small>客户</small></div></div><nav class="portal-nav"><button class="portal-return" @click="router.push('/')"><span>⌂</span> 返回前台</button><div class="portal-divider"></div><button v-for="item in items" :key="item.key" :class="{active:active===item.key}" @click="active=item.key"><span class="portal-icon">{{item.icon}}</span>{{item.label}}</button></nav><button class="portal-logout" @click="logout"><span>↪</span> 退出登录</button></aside><main class="portal-main"><header class="portal-content-header"><div><p>当前位置 / {{currentTitle}}</p><h1>{{currentTitle}}</h1></div><div class="portal-header-badge customer">客户中心</div></header><section class="portal-content-body"><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取客户数据…</div><template v-else><div v-if="active==='dashboard'" class="portal-dashboard"><div class="portal-stat-grid"><article><span>总资产</span><strong>¥{{money(asset?.total_asset)}}</strong></article><article><span>可用余额</span><strong>¥{{money(account?.available_balance)}}</strong></article><article><span>持仓市值</span><strong>¥{{money(totalHoldingValue)}}</strong></article></div><div class="portal-panel dashboard-asset-note"><strong>资产数据说明</strong><span>总资产 = 可用余额 + 冻结余额 + 当前持仓市场价值；每次进入客户中心会按最新持仓估值刷新。</span></div></div><div v-else-if="active==='advisor'" class="portal-panel"><h2>投顾服务</h2><p>查看当前投顾授权、操作草稿并完成客户确认。</p><RouterLink class="button" to="/customer-center/advisor">进入投顾服务</RouterLink></div><div v-else-if="active==='risk'" class="portal-panel"><h2>风险测评</h2><p>完成风险测评，系统将根据结果判断产品适配范围。</p><RouterLink class="button" to="/customer-center/risk-assessment">进入风险测评</RouterLink></div><div v-else-if="active==='enterprise'" class="portal-panel"><h2>企业客户认证</h2><p>提交企业资料，审核通过后可转为企业客户。</p><RouterLink class="button" to="/customer-center/enterprise-verification">进入认证申请</RouterLink></div><div v-else-if="active==='profile'" class="portal-panel"><h2>个人信息</h2><p v-if="profileMessage" class="success">{{profileMessage}}</p><p v-if="profileError" class="error">{{profileError}}</p><form class="product-editor-grid" @submit.prevent="saveProfile"><label>用户名<input :value="auth.me.value?.username" disabled></label><label>显示名称<input :value="auth.me.value?.display_name" disabled></label><label>年龄<input v-model.number="profile.age" type="number" min="0" max="150"></label><label>职业<input v-model="profile.occupation"></label><label>地区<input v-model="profile.region"></label><label class="full">投资目标<select v-model="profile.investment_goal"><option value="capital_preservation">资产保值</option><option value="income">稳定收益</option><option value="balanced">均衡配置</option><option value="growth">资产增长</option><option value="aggressive">高风险增值</option></select></label><label>投资期限（年）<input v-model.number="profile.investment_horizon_years" type="number" min="0" max="100"></label><label>流动性偏好<select v-model="profile.liquidity_preference"><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label><label class="full"><button class="button" :disabled="savingProfile">{{savingProfile?'保存中':'保存个人信息'}}</button></label></form></div><OrdersView v-else-if="active==='orders'"/><div v-else-if="active==='assets'" class="asset-workspace"><div class="asset-hero"><div><span>总资产</span><strong>¥{{money(asset?.total_asset)}}</strong><small>快照时间 {{asset?.snapshot_time?new Date(asset.snapshot_time).toLocaleString('zh-CN',{hour12:false}):'实时派生'}}</small></div><div class="asset-hero-metrics"><p><span>现金资产</span><strong>¥{{money(asset?.cash_balance)}}</strong></p><p><span>净资产</span><strong>¥{{money(asset?.net_asset)}}</strong></p><p><span>累计浮盈</span><strong class="positive-value">+¥{{money(totalProfit)}}</strong></p></div></div><div class="asset-chart-grid"><section class="asset-chart-card trend-card"><div class="chart-card-head"><div><span>ASSET HISTORY</span><h3>资产趋势</h3></div><small>{{history.length}} 个快照</small></div><div v-if="history.length>1" class="trend-chart"><div class="trend-axis"><span>¥{{money(chartMax)}}</span><span>¥{{money(chartMin)}}</span></div><svg viewBox="0 0 560 180" role="img" aria-label="总资产趋势"><defs><linearGradient id="assetArea" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#3a6cf4" stop-opacity=".28"/><stop offset="1" stop-color="#3a6cf4" stop-opacity="0"/></linearGradient></defs><polyline :points="chartPoints+' 546,166 14,166'" fill="url(#assetArea)" stroke="none"/><polyline :points="chartPoints" fill="none" stroke="#3a6cf4" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></div><div v-else class="chart-empty">完成更多交易、赎回或转账后，这里会形成资产趋势。</div></section><section class="asset-chart-card allocation-card"><div class="chart-card-head"><div><span>ALLOCATION</span><h3>资产配置</h3></div></div><div class="allocation-wrap"><div class="allocation-donut" :style="{background:allocationStyle}"><div><strong>{{cashShare}}%</strong><span>现金</span></div></div><div class="allocation-legend"><p><i class="cash-dot"></i><span>现金资产</span><strong>¥{{money(asset?.cash_balance)}}</strong></p><p><i class="holding-dot"></i><span>持仓市值</span><strong>¥{{money(totalHoldingValue)}}</strong></p></div></div></section><section class="asset-chart-card profit-card"><div class="chart-card-head"><div><span>HOLDING P&L</span><h3>持仓收益</h3></div><small class="positive-value">+¥{{money(totalProfit)}}</small></div><div v-if="holdings.length" class="profit-bars"><div v-for="holding in holdings" :key="holding.id" class="profit-row"><div><strong>{{holding.product_name||'未知产品'}}</strong><small>日收益 +{{(Number(holding.daily_yield_rate||0)*100).toFixed(3)}}%</small></div><div class="profit-track"><span :style="{width:Math.max(5,Math.abs(Number(holding.profit_loss||0))/maxProfit*100)+'%'}"></span></div><b>+¥{{money(holding.profit_loss)}}</b></div></div><div v-else class="chart-empty">暂无持仓收益数据。</div></section></div><div class="asset-table-panel"><div class="asset-panel-head"><div><span>POSITION BOOK</span><h2>当前持仓</h2></div><small>共 {{holdings.length}} 项</small></div><div class="module-table-wrap"><table class="admin-table asset-table"><thead><tr><th>产品名称</th><th>日收益率</th><th>持有数量</th><th>成本金额</th><th>市场价值</th><th>累计收益率</th><th>浮动盈亏</th><th>持有天数</th><th>状态</th></tr></thead><tbody><tr v-for="holding in holdings" :key="holding.id"><td><strong>{{holding.product_name||'未知产品'}}</strong><small class="holding-product-id">{{holding.product_id}}</small></td><td class="yield-rate">+{{(Number(holding.daily_yield_rate||0)*100).toFixed(3)}}%</td><td>{{Number(holding.quantity||0).toLocaleString()}}</td><td>¥{{money(holding.cost_amount)}}</td><td>¥{{money(holding.market_value)}}</td><td class="positive-value">+{{(Number(holding.cumulative_return_rate||0)*100).toFixed(2)}}%</td><td :class="Number(holding.profit_loss)>=0?'positive-value':'negative-value'">{{Number(holding.profit_loss)>=0?'+':''}}¥{{money(holding.profit_loss)}}</td><td>{{holding.holding_days||0}} 天</td><td><span class="status-chip settled">{{holding.status==='active'?'持有中':holding.status}}</span></td></tr><tr v-if="!holdings.length"><td colspan="9" class="table-empty">暂无持仓</td></tr></tbody></table></div></div></div><div v-else class="portal-panel"><h2>{{currentTitle}}</h2><p>该功能正在建设中。</p></div></template></section></main></div>
</template>
